<?php
$uid = (int)$u['id'];
handle('iou_add', function () use ($uid) { Ious::create($uid, (string)$_POST['who'], (string)$_POST['amount'], (string)$_POST['due'], (string)($_POST['note'] ?? '')); return 'IOU recorded and the borrower was notified.'; });
handle('iou_repay', function () use ($uid) { Auth::verifyPin($uid, (string)($_POST['pin'] ?? '')); Ious::repay($uid, (int)$_POST['id'], cents($_POST['amount'] ?? ''), idem_key()); return 'Repayment sent.'; });
handle('iou_remind', function () use ($uid) { Ious::remind($uid, (int)$_POST['id']); return 'Reminder sent.'; });
handle('iou_cancel', function () use ($uid) { $id = (int)$_POST['id']; if (Ious::paid($id) > 0) throw new AppError('Cannot cancel an IOU that already has repayments.'); q("UPDATE ious SET status='cancelled' WHERE id=? AND lender_id=? AND status='open'", [$id, $uid]); return 'IOU cancelled.'; });
echo page_head('IOU tracker', 'Money you lent or borrowed, with due dates and partial repayments.');
$mk = function (array $list, bool $lender) use ($uid) { $rows = [];
  foreach ($list as $i) { $paid = Ious::paid((int)$i['id']); $left = cents($i['amount']) - $paid; $late = in_array($i['status'], ['open', 'partial'], true) && $i['due_date'] < date('Y-m-d');
    $act = ''; if (in_array($i['status'], ['open', 'partial'], true)) $act = $lender ? form_start('iou_remind', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$i['id'] . '">' . btn('Remind', 'secondary sm') . '</form>' . ($paid == 0 ? ' ' . form_start('iou_cancel', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$i['id'] . '">' . btn('Cancel', 'secondary sm') . '</form>' : '') : form_start('iou_repay') . '<input type="hidden" name="id" value="' . (int)$i['id'] . '"><div class="row"><input name="amount" inputmode="decimal" placeholder="' . e(dec($left)) . '" required style="min-width:90px" aria-label="Amount"><input name="pin" type="password" inputmode="numeric" maxlength="6" placeholder="PIN" required style="min-width:70px" aria-label="PIN">' . btn('Repay', 'sm') . '</div></form>';
    $rows[] = [e($i['name']) . '<div class="hint">' . e($i['note']) . '</div>', mny($i['amount']) . '<div class="hint">paid ' . mny(dec($paid)) . ', left ' . mny(dec($left)) . '</div>', e(fdate($i['due_date'], false)) . ($late ? ' ' . badge('overdue') : ''), badge($i['status']), $act]; } return $rows; };
$lent = rows('SELECT i.*, u.name FROM ious i JOIN users u ON u.id=i.borrower_id WHERE i.lender_id=? ORDER BY i.id DESC', [$uid]); $owed = rows('SELECT i.*, u.name FROM ious i JOIN users u ON u.id=i.lender_id WHERE i.borrower_id=? ORDER BY i.id DESC', [$uid]);
echo '<div class="grid g-main"><div class="grid">' . card('I owe', tbl(['Lender', 'Amount', 'Due', 'Status', ''], $mk($owed, false), 'You do not owe anyone.')) . card('Owed to me', tbl(['Borrower', 'Amount', 'Due', 'Status', ''], $mk($lent, true), 'No one owes you.')) . '</div>' .
  card('Record an IOU', form_start('iou_add') . field('Borrower', 'who', 'text', '', 'required placeholder="email or phone"') . field('Amount (BDT)', 'amount', 'text', '', 'required inputmode="decimal"') . field('Due date', 'due', 'date', date('Y-m-d', strtotime('+14 days')), 'required') . field('Note', 'note', 'text', '', 'maxlength="200"') . btn('Record IOU') . '</form><p class="hint">Reminders are sent automatically 2 days before the due date.</p>') . '</div>';
